ALTER TABLE lamontana.intento_activacion_configuracion
 ADD COLUMN id_usuario_actor bigint REFERENCES lamontana.usuario,
 ADD COLUMN id_operacion uuid UNIQUE REFERENCES lamontana.autorizacion_configuracion(id_operacion),
 DROP CONSTRAINT intento_activacion_configuracion_origen_check,
 ADD CONSTRAINT intento_activacion_configuracion_origen_check CHECK(origen IN ('MANUAL','PROGRAMACION','REINTENTO','RECUPERACION')),
 ADD CONSTRAINT intento_activacion_actor CHECK((origen='MANUAL' AND id_usuario_actor IS NOT NULL AND id_operacion IS NOT NULL)
    OR (origen<>'MANUAL' AND id_usuario_actor IS NULL AND id_operacion IS NULL));
ALTER TABLE lamontana.autorizacion_configuracion DROP CONSTRAINT autorizacion_configuracion_proposito_check, ADD CONSTRAINT autorizacion_configuracion_proposito_check CHECK(proposito IN ('CANCELAR_BORRADOR','ACTIVAR_CONFIGURACION','PROGRAMAR_CONFIGURACION','CANCELAR_PROGRAMACION','ADELANTAR_CONFIGURACION'));
ALTER TABLE lamontana.comprobante_configuracion DROP CONSTRAINT comprobante_configuracion_tipo_check, ADD CONSTRAINT comprobante_configuracion_tipo_check CHECK(tipo IN ('CREAR_BORRADOR','GUARDAR_MODELO','CANCELAR_BORRADOR','GUARDAR_PAGOS','GUARDAR_RECURSOS','ALTA_IMPRESORA','EDITAR_IMPRESORA','ESTADO_IMPRESORA','RETIRAR_IMPRESORA','GUARDAR_ENTREGA','ALTA_PUNTO','EDITAR_PUNTO','ALTA_ZONA','EDITAR_ZONA','ACTIVAR_CONFIGURACION','PROGRAMAR_CONFIGURACION','CANCELAR_PROGRAMACION','ADELANTAR_CONFIGURACION'));
ALTER TABLE lamontana.evento_configuracion DROP CONSTRAINT evento_configuracion_tipo_check, ADD CONSTRAINT evento_configuracion_tipo_check CHECK(tipo IN ('BORRADOR_CREADO','MODELO_SELECCIONADO','CANCELACION_SOLICITADA','BORRADOR_CANCELADO','PAGOS_CONFIGURADOS','RECURSOS_CONFIGURADOS','IMPRESORA_CREADA','IMPRESORA_EDITADA','IMPRESORA_ESTADO_CAMBIADO','IMPRESORA_RETIRADA','ENTREGA_CONFIGURADA','PUNTO_CREADO','PUNTO_EDITADO','ZONA_CREADA','ZONA_EDITADA','ACTIVACION_SOLICITADA','CONFIGURACION_ACTIVADA','CONFIGURACION_HISTORICA','AUTORIZACION_RECHAZADA','PROGRAMACION_SOLICITADA','CONFIGURACION_PROGRAMADA','PROGRAMACION_CANCELADA','INTENTO_MANUAL_INICIADO'));
